def f(inp):
    H,W=len(inp),len(inp[0])
    # separator rows/cols: rows/cols that are entirely one nonzero color (the grid bg)
    from collections import Counter
    sepc={}
    for r in range(H):
        vals=set(inp[r])-{0}
        if len(vals)==1: sepc['row']=r
    for c in range(W):
        col=[inp[r][c] for r in range(H)]
        s=set(col)-{0}
        if len(s)==1: sepc['col']=c
    bg=list(sepc.values())[0]
    rem=[r for r in range(H) if r not in sepc['row']]
    bands=[]; cur=[]
    prev=None
    for r in rem:
        if prev is None or r-prev>1: 
            if cur: bands.append(cur); cur=[]
        cur.append(r); prev=r
    cur.append(prev) if False else None
    bands.append(cur)
    marks=[(r,c,inp[r][c]) for r in range(H) for c in range(W) if inp[r][c] not in (0,bg)]
    # band = rows strictly between separators
    seprows=sorted(sepc['row'])
    bands2=[r for r in range(H) if r not in seprows]
    # group consecutive
    bgroups=[]; g=[]
    for r in bands2:
        if g and r-g[-1]==1: g.append(r)
        else:
            if g: bgroups.append(g)
            g=[r]
    if g: bgroups.append(g)
    markbands=[i for i,g in enumerate(bgroups) if any(inp[r][c]!=0 and inp[r][c]!=bg for r in g for c in range(W))]
    mb=bgroups[markbands[0]]
    h=max(mb)-min(mb)+1
    stamp_rows=mb[:h//2+ (h%2)]  # top half
    sc=sorted({c for _,c,_ in marks if min(mb)<=_<=max(mb)})
    # column groups similarly
    cols2=[c for c in range(W) if c not in sepc['col']]
    cg=[]; g2=[]
    for c in cols2:
        if g2 and c-g2[-1]==1: g2.append(c)
        else:
            if g2: cg.append(g2)
            g2=[c]
    if g2: cg.append(g2)
    mcols=[j for j,g2 in enumerate(cg) if any(inp[r][c]!=0 and inp[r][c]!=bg for r in mb for c in g2)]
    mc=cg[mcols[0]]
    sh=len(mc)
    stamp=[[inp[r][c] if (r,c,inp[r][c]) in [(rr,cc,v) for rr,cc,v in marks] else 0 for c in mc] for r in stamp_rows]
    out=[row[:] for row in inp]
    for br in range(len(bgroups)):
        for bc in range(len(cg)):
            r0,bw=bgroups[br][0],cg[bc][0]
            for i,rr in enumerate(stamp):
                for j,v in enumerate(rr):
                    if v: out[r0+i][bw+j]=v
    return out

